const $ = s => document.querySelector(s);
const money=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});
const returnKeys=['date','time','departure_station','departure_address','arrival_date','arrival_time','arrival_station','arrival_address','ticket_price'];
const rentalKeys=['location_mode','pickup_location','dropoff_location','dropoff_date','dropoff_time','group','model','mileage_mode','km_per_day','protection','daily_price','protection_price','fee_percent','pickup_street','pickup_number','pickup_district','pickup_city','pickup_state','pickup_landmark','dropoff_street','dropoff_number','dropoff_district','dropoff_city','dropoff_state','dropoff_landmark'];
const tourTypes={"culture":["Cultura e história","Museus, monumentos, centros históricos, teatros e igrejas."],"nature":["Natureza e ecoturismo","Parques, trilhas, cachoeiras, mirantes e reservas ambientais."],"beach":["Sol e praia","Praias, ilhas, passeios de barco e clubes de praia."],"adventure":["Aventura e esportes","Trilhas pesadas, rafting, tirolesa, mergulho, ciclismo e eventos esportivos."],"gastronomy":["Gastronomia","Restaurantes, cafés, vinícolas, feiras, mercados locais e tours gastronômicos."],"nightlife":["Entretenimento e vida noturna","Shows, parques temáticos, bares, casas noturnas e cinemas."],"shopping":["Compras","Shoppings, feiras de artesanato, outlets e ruas de comércio."],"wellness":["Bem-estar e relaxamento","Spas, termas, retiros e passeios contemplativos."],"guided":["Tours guiados","City tours, excursões bate-volta e experiências locais com guia."]};
const tourKeys=['duration_hours','duration_minutes','full_price','half_price','full_quantity','half_quantity','advance_required'];
const paymentMethods={pix:'Pix',bank_transfer:'Transferência bancária',debit:'Débito',credit_once:'Crédito à vista',credit_installments:'Crédito parcelado'};
const stayTypes={"seasonal":"Aluguel por temporada","hotel":"Hotel","resort":"Resort","inn":"Pousada","hostel":"Hostel","aparthotel":"Flat / Apart-hotel","cabin":"Chalé / Cabana","camping":"Camping","family":"Casa de familiares ou amigos","farm":"Hotel-fazenda","bnb":"Cama e café (B&B)","glamping":"Glamping","motorhome":"Motorhome / Trailer","room":"Quarto em residência"};
const stayKeys=['checkin_time','departure_date','departure_time','checkout_time'];
const foodTypes={restaurant:'Restaurante',cafe:'Café / Lanche',dessert:'Sobremesa',drinks:'Bar / Bebidas',market:'Mercado'};
const busTypes={international:'Ônibus Internacional',interstate:'Ônibus Interestadual',intercity:'Ônibus Intermunicipal',metropolitan:'Ônibus Metropolitano',municipal:'Ônibus Municipal'};
const mobilityTypes={app:'Transporte por App',bus:'Ônibus',rental_car:'Aluguel de carro',own_car:'Carro próprio',own_motorcycle:'Moto própria'};
const categories = {car:['Mobilidade','🚙'],stay:['Hospedagem','🛎️'],tour:['Passeios','🎟️'],food:['Comer & Beber','🍽️']};
let items=[],filter='all',client=null,user=null,approved=false,busy=false;
const configured=Boolean(window.ROTA_CONFIG?.supabaseUrl && window.ROTA_CONFIG?.supabaseKey);
const escape = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function safeUrl(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function render(){
 $('.workspace').hidden=!approved;
 $('#accessGate').hidden=approved;
 if(!approved && $('#editor').open) $('#editor').close();
 $('#account').hidden=!user;
 $('#add').hidden=!approved;
 $('#filters').innerHTML=[['all','Todos'],...Object.entries(categories).map(([k,v])=>[k,v[0]])].map(([key,label])=>`<button data-filter="${key}" class="${filter===key?'active':''}" aria-pressed="${filter===key}">${label}</button>`).join('');
 const visible=timelineItems(items).filter(i=>filter==='all'||categoryGroup(i)===filter).sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||'')));
 const groups=Object.groupBy(visible,i=>i.date);
 $('#timeline').innerHTML=Object.entries(groups).map(([date,rows])=>{const d=new Date(date+'T12:00:00');return `<section class="day"><div class="date">${d.toLocaleDateString('pt-BR',{weekday:'short'})}<strong>${d.getDate()}</strong><small>${d.toLocaleDateString('pt-BR',{month:'short'})}</small></div><div class="cards">${rows.map(i=>i.category==='bus'?(isDetailedBusItem(i)?renderBusCard(i):renderPointCard(i)):i.mobility_type==='app'?renderPointCard(i):i.category==='stay'?renderStayCard(i):i.category==='tour'?renderTourCard(i):`<button class="card" data-id="${escape(i.id)}" aria-label="Editar ${escape(i.title)}"><span class="icon ${escape(i.category)}">${i.category==='bus'?'🚌':i.category==='car'&&i.mobility_type==='own_motorcycle'?'🏍️':(categories[i.category]?.[1]||'📍')}</span><div class="card-body"><div class="card-top"><span class="tag">${i.category==='food'?(foodTypes[i.food_type]||'Comer & Beber'):i.category==='bus'?'Ônibus':i.category==='car'?(mobilityTypes[i.mobility_type]||'Aluguel de carro'):(categories[i.category]?.[0]||'Item')}${i.leg?' · '+i.leg:''}${i.time?' · '+escape(i.time.slice(0,5)):''}</span><span class="status ${i.status==='A planejar'?'pending':''}">${escape(i.status)}</span></div><h3>${escape(i.title)}</h3><p>${escape(i.category==='bus'?(i.departure_station||i.place||'Rodoviária a definir')+' → '+(i.arrival_station||'Destino a definir'):(i.place||'Local a definir'))}</p>${i.category==='bus'&&i.arrival_date?`<p>Chegada: ${escape(new Date(i.arrival_date+'T12:00:00').toLocaleDateString('pt-BR'))}${i.arrival_time?' · '+escape(i.arrival_time.slice(0,5)):''}</p>`:''}${i.category==='bus'&&(i.ticket_price!=null||i.extra_costs?.length)?`<p>Total: ${escape(money.format(costCents(i.ticket_price,i.extra_costs)/100))}</p>`:''}${i.rental?`<p>Devolução: ${escape(new Date(i.rental.dropoff_date+'T12:00:00').toLocaleDateString('pt-BR'))} · ${escape(i.rental.dropoff_time)} · ${escape(i.rental.days)} diária(s)</p><p>Total do aluguel: ${escape(money.format(i.rental.total))}</p>`:''}${i.reference?`<p>Reserva: ${escape(i.reference)}</p>`:''}</div><span class="arrow">↗</span></button>`).join('')}</div></section>`}).join('')||`<p class="empty">${configured&&!user?'Seu próximo caminho começa com um acesso seguro.':'Nenhum item por aqui. Que tal começar seu roteiro?'}</p>`;
 renderBudget();
}
function edit(id){if(!approved){$('#login').showModal();return}const form=$('#itemForm');form.reset();const item=items.find(i=>i.id===id);for(const key of ['id','category','title','date','time','place','reference','status','url','notes','departure_station','departure_address','arrival_date','arrival_time','arrival_station','arrival_address'])if(item)form.elements[key].value=item[key]||'';if(!item)form.elements.date.value=new Date().toLocaleDateString('en-CA');renderExtraCosts(item?.extra_costs||[]);renderExtraCosts(item?.return_leg?.extra_costs||[],'returnExtraCosts');form.elements.ticket_price.value=item?.ticket_price??'';form.elements.item_price.value=item?.ticket_price??'';form.elements.bus_type.value=item?.bus_type||'interstate';form.elements.point_origin.value=item?.departure_station||item?.place||'';form.elements.point_destination.value=item?.arrival_station||'';form.elements.point_origin_city.value=item?.transport_details?.origin_city||'';form.elements.point_destination_city.value=item?.transport_details?.destination_city||'';form.elements.food_type.value=item?.food_type||'restaurant';form.elements.stay_type.value=item?.lodging?.type||'seasonal';for(const key of stayKeys)form.elements['stay_'+key].value=item?.lodging?.[key]||'';form.elements.category.value=item?.category==='bus'?'car':item?.category||'car';form.elements.mobility_type.value=item?.category==='bus'?'bus':item?.mobility_type||'bus';for(const key of rentalKeys){const input=form.elements['rental_'+key];const fallback={location_mode:'same',mileage_mode:'unlimited',protection:'basic',fee_percent:0};input.value=item?.rental?.[key]??fallback[key]??'';}form.elements.journey_type.value=item?.return_leg?'round_trip':'one_way';for(const key of returnKeys)form.elements['return_'+key].value=item?.return_leg?.[key]??'';form.elements.payment_payer.value=item?.payment?.payer||'';form.elements.payment_method.value=item?.payment?.method||'';form.elements.payment_installments.value=item?.payment?.installments??'';form.elements.payment_first_date.value=item?.payment?.first_date||'';form.elements.tour_type.value=item?.tour?.type||'culture';const duration=item?.tour?.duration_minutes;for(const key of tourKeys){const fallback={full_quantity:1,half_quantity:0,advance_required:'no'};form.elements['tour_'+key].value=key==='advance_required'?(item?.tour?.advance_required?'yes':'no'):key==='duration_hours'?(duration!=null?Math.floor(duration/60):''):key==='duration_minutes'?(duration!=null?duration%60:''):item?.tour?.[key]??fallback[key]??'';}beginCategoryDraft(item);syncCategory();updateCostTotal();$('#remove').hidden=!form.elements.id.value;$('#editorTitle').textContent=form.elements.id.value?'Detalhes do plano':draftDirty?'Continuar preenchimento':'Adicionar ao roteiro';startWizard(Boolean(item));$('#editor').showModal();focusWizard();}
async function load(){approved=false;items=[];render();if(!user)return;const access=await client.rpc('is_travel_member');if(access.error)throw access.error;if(!access.data){$('#accessMessage').textContent='Este e-mail ainda não foi aprovado pelo responsável.';return}const {data,error}=await client.from('travel_items').select('*');if(error)throw error;items=data;approved=true;$('#accessMessage').textContent='';render();if($('#login').open)$('#login').close()}
$('#filters').onclick=e=>{if(e.target.dataset.filter){filter=e.target.dataset.filter;render()}};
$('#timeline').onclick=e=>{const card=e.target.closest('[data-id]');if(card)edit(card.dataset.id)};
$('#add').onclick=$('#addBottom').onclick=()=>edit();
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());
$('#account').onclick=async()=>{if(user){const {error}=await client.auth.signOut();if(error){toast('Não foi possível sair. Tente novamente.');return}user=null;approved=false;items=[];render()}else $('#login').showModal()};
function collectItemValues(){const values=Object.fromEntries(new FormData($('#itemForm')));delete values.id;if(values.category==='car'&&values.mobility_type==='bus')values.category='bus';values.bus_type=values.category==='bus'?(values.bus_type||'interstate'):null;preparePointTransport(values);values.food_type=values.category==='food'?(values.food_type||'restaurant'):null;values.mobility_type=values.category==='car'?(values.mobility_type||'rental_car'):null;values.ticket_price=isDetailedBusItem(values)&&values.ticket_price!=null&&values.ticket_price!==''?parseMoney(values.ticket_price):values.item_price!=null&&values.item_price!==''?parseMoney(values.item_price):null;delete values.item_price;prepareRental(values);prepareReturn(values);prepareStay(values);preparePayment(values);prepareTour(values);values.extra_costs=isDetailedBusItem(values)?readExtraCosts():[];if(values.url&&!safeUrl(values.url))throw new Error('Use um link http ou https válido.');values.time=values.time||null;if(isDetailedBusItem(values)){if(!values.time||!values.arrival_date||!values.arrival_time||!values.departure_station?.trim()||!values.departure_address?.trim()||!values.arrival_station?.trim()||!values.arrival_address?.trim())throw new Error('Preencha os dados de saída e chegada.');if(values.arrival_date+'T'+values.arrival_time<values.date+'T'+values.time)throw new Error('A chegada não pode ser anterior à partida.');values.place=values.departure_station;}else if(values.category!=='bus'&&values.mobility_type!=='app'){for(const key of ["departure_station","departure_address","arrival_date","arrival_time","arrival_station","arrival_address"])values[key]=null;}return values;}
async function saveCurrentItem(values=collectItemValues()){if(!approved||!client||!user)throw new Error('Entre com um e-mail aprovado para salvar.');const form=$('#itemForm'),id=form.elements.id.value;if(id&&!items.some(item=>item.id===id&&categoryGroup(item)===form.elements.category.value))throw new Error('Este item pertence a outra categoria. Abra o item novamente para editar.');const result=id?await client.from('travel_items').update(values).eq('id',id).select():await client.from('travel_items').insert(values).select();if(result.error){if(result.error.code==='PGRST204'||result.error.code==='42703')throw new Error('O banco precisa ser atualizado para salvar estes dados do roteiro.');throw result.error;}const saved=result.data?.[0];if(!saved?.id)throw new Error('Sua autorização pode ter sido revogada.');form.elements.id.value=saved.id;items=items.filter(item=>item.id!==saved.id).concat(saved);draftDirty=false;persistCategoryDraft();render();return saved;}
$('#itemForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const button=e.submitter||$('#wizardSave');busy=true;setDraftBusy(true);try{persistCategoryDraft();await saveCurrentItem();clearCategoryDraft(activeDraftCategory);draftDirty=false;$('#editor').close();toast('Item salvo no roteiro.');if(button.dataset.addAnother==='true')edit();}catch(err){persistCategoryDraft();setDraftStatus('Não foi salvo no roteiro. O preenchimento foi mantido.');toast(err.message||'Não foi possível salvar.');}finally{busy=false;setDraftBusy(false)}};
$('#remove').onclick=async()=>{if(busy||!confirm('Excluir este item do roteiro? Em viagens de ida e volta, os dois trechos serão excluídos.'))return;busy=true;try{const id=$('#itemForm').elements.id.value;if(!approved||!client)throw new Error('Acesso não autorizado.');{const {data,error}=await client.from('travel_items').delete().eq('id',id).select();if(error)throw error;if(!data?.length)throw new Error('Não foi possível excluir. Verifique seu acesso.');await load()}clearCategoryDraft(activeDraftCategory);draftDirty=false;$('#editor').close();toast('Item excluído.')}catch(err){toast(err.message)}finally{busy=false}};
let loginSending=false,loginCooldownUntil=0,loginTimer;
function loginErrorMessage(error){
 if(error?.code==='over_email_send_rate_limit'||/email rate limit/i.test(error?.message||'')) return 'O limite de envio de e-mails foi atingido. Aguarde até uma hora antes de solicitar um novo link. Para uso contínuo, o responsável precisa configurar um serviço próprio de envio (SMTP).';
 if(error?.status===429||error?.code==='over_request_rate_limit') return 'Muitas solicitações em pouco tempo. Aguarde alguns minutos antes de tentar novamente.';
 if(/fetch|network|connection/i.test(error?.message||'')) return 'Não foi possível conectar ao serviço de acesso. Confira sua conexão e tente novamente.';
 return 'Não foi possível enviar o link. Confira se seu e-mail foi cadastrado pelo responsável. Se persistir, verifique o serviço de envio no Supabase.';
}
function updateLoginButton(){const button=$('#loginForm').querySelector('button[type="submit"]');const remaining=Math.max(0,Math.ceil((loginCooldownUntil-Date.now())/1000));button.disabled=loginSending||remaining>0;button.textContent=loginSending?'Enviando…':remaining?'Tentar novamente em '+(remaining>=60?Math.ceil(remaining/60)+' min':remaining+' s'):'Receber link de acesso ↗';if(!remaining&&!loginSending)clearInterval(loginTimer)}
$('#loginForm').onsubmit=async e=>{e.preventDefault();if(loginSending||Date.now()<loginCooldownUntil)return;const message=$('#loginMessage');if(!configured||!client){message.textContent='O acesso por e-mail ainda precisa ser configurado pelo responsável. O roteiro permanece bloqueado.';return}loginSending=true;message.textContent='Solicitando link de acesso…';updateLoginButton();let cooldown=0;try{const {error}=await client.auth.signInWithOtp({email:e.target.elements.email.value.trim(),options:{shouldCreateUser:false,emailRedirectTo:location.origin+location.pathname}});if(error)throw error;message.textContent='Se o e-mail estiver cadastrado, você receberá um link de acesso. Confira também o spam e use o e-mail mais recente.';cooldown=60}catch(error){message.textContent=loginErrorMessage(error);cooldown=error?.code==='over_email_send_rate_limit'||/email rate limit/i.test(error?.message||'')?3600:error?.status===429?60:0}finally{loginSending=false;loginCooldownUntil=Date.now()+cooldown*1000;updateLoginButton();if(cooldown){clearInterval(loginTimer);loginTimer=setInterval(updateLoginButton,1000)}}};

if(!configured){render();$('#accessMessage').textContent='Aguardando configuração do acesso por e-mail pelo responsável.';}else{render();try{const {createClient}=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');client=createClient(window.ROTA_CONFIG.supabaseUrl,window.ROTA_CONFIG.supabaseKey);const {data,error}=await client.auth.getSession();if(error)throw error;user=data.session?.user||null;await load();client.auth.onAuthStateChange((_event,session)=>{user=session?.user||null;if(!user){approved=false;items=[];render()}else setTimeout(()=>load().catch(()=>toast('Falha ao carregar o roteiro. Verifique sua autorização.')),0)})}catch{user=null;items=[];render();toast('Não foi possível conectar ao acesso privado. Confira a configuração e recarregue.');$('#account').disabled=true}}

$('#gateLogin').onclick=()=>$('#login').showModal();

// Atualiza instalações antigas sem copiar dados locais para o banco.
if('serviceWorker' in navigator) navigator.serviceWorker.getRegistrations().then(registrations=>Promise.all(registrations.filter(r=>r.scope===new URL('./',location.href).href).map(r=>r.update()))).catch(()=>{});
function syncCategory(){const form=$('#itemForm'),category=form.elements.category.value,food=category==='food',mobility=category==='car',bus=isBusForm(),detailed=isDetailedBusForm(),app=mobility&&form.elements.mobility_type.value==='app',point=(bus&&!detailed)||app,metro=bus&&form.elements.bus_type.value==='metropolitan';$('#foodField').hidden=!food;form.elements.food_type.disabled=!food;$('#mobilityField').hidden=!mobility;for(const input of $('#mobilityField').querySelectorAll('input'))input.disabled=!mobility;$('#busTypeField').hidden=!bus;for(const input of $('#busTypeField').querySelectorAll('input'))input.disabled=!bus;$('#journeyField').hidden=!detailed;for(const input of $('#journeyField').querySelectorAll('input'))input.disabled=!detailed;syncJourney();$('#busFields').hidden=!detailed;$('#journeyTotalField').hidden=!detailed;$('#costFields').hidden=!detailed;for(const input of $('#costFields').querySelectorAll('input'))input.disabled=!detailed;for(const input of $('#busFields').querySelectorAll('input')){input.disabled=!detailed;input.required=detailed;}$('#pointTransportFields').hidden=!point;for(const name of ['point_origin','point_destination']){form.elements[name].disabled=!point;form.elements[name].required=point;}$('#transportCities').hidden=!metro;for(const name of ['point_origin_city','point_destination_city']){form.elements[name].disabled=!metro;form.elements[name].required=metro;}$('#placeField').hidden=bus||app;form.elements.place.disabled=bus||app;form.elements.time.required=bus||app;$('#titleLabel').textContent=bus?'Empresa':app?'Aplicativo / Empresa':food?'Estabelecimento':'Título';form.elements.title.placeholder=bus?'Nome da empresa de ônibus':app?'Ex.: Uber, 99 ou outro aplicativo':food?'Ex.: Restaurante, café ou bar':'Ex.: Check-in na pousada';$('#dateLabel').textContent=detailed?'Data de saída':point?'Data prevista':'Data';$('#timeLabel').textContent=detailed?'Horário de partida':point?'Horário previsto':'Horário';$('#urlLabel').textContent=point?'Link de informação':bus?'Link da empresa':food?'Link do estabelecimento':'Link da reserva ou voucher';syncRental();const genericPrice=category!=='tour'&&!detailed&&!(mobility&&form.elements.mobility_type.value==='rental_car');$('#itemPriceField').hidden=!genericPrice;form.elements.item_price.disabled=!genericPrice;syncStay();syncPayment();syncTour();renderWizard();}
$('#categoryPicker').addEventListener('change',switchDraftCategory);


function parseMoney(value){const n=Number(value);if(!Number.isFinite(n)||n<0||n>9999999999.99||Math.abs(n*100-Math.round(n*100))>0.001)throw new Error('Informe um valor válido, positivo ou zero, com até duas casas decimais.');return Math.round(n*100)/100;}
function costCents(ticket,extras=[]){return Math.round(Number(ticket||0)*100)+(extras||[]).reduce((sum,row)=>sum+Math.round(Number(row.amount||0)*100),0);}
function renderExtraCosts(rows,target='extraCosts'){$('#'+target).innerHTML='';for(const row of rows)addCostRow(row,target);}
function addCostRow(row={},target='extraCosts'){const div=document.createElement('div');div.className='extra-cost';div.innerHTML='<label>Descrição<input class="cost-description" maxlength="120" required placeholder="Ex.: Taxa de embarque" value="'+escape(row.description||'')+'"></label><label>Valor (R$)<input class="cost-amount" type="number" min="0" max="9999999999.99" step="0.01" inputmode="decimal" required value="'+escape(row.amount??'')+'"></label><button type="button" class="danger remove-cost" aria-label="Remover valor" title="Remover valor">✕</button>';$('#'+target).append(div);updateCostTotal();}
function readExtraCosts(target='extraCosts'){return [...$('#'+target).querySelectorAll('.extra-cost')].map(row=>{const description=row.querySelector('.cost-description').value.trim(),amount=row.querySelector('.cost-amount').value;if(!description||amount==='')throw new Error('Preencha a descrição e o valor dos custos adicionais, ou remova a linha.');return {description,amount:parseMoney(amount)};});}
function updateCostTotal(){const form=$('#itemForm');const amounts=target=>[...$('#'+target).querySelectorAll('.cost-amount')].map(input=>({amount:Number(input.value)||0}));const outbound=costCents(Number(form.elements.ticket_price.value)||0,amounts('extraCosts'));const round=isDetailedBusForm()&&form.elements.journey_type.value==='round_trip';const inbound=round?costCents(Number(form.elements.return_ticket_price.value)||0,amounts('returnExtraCosts')):0;$('#outboundCostTotal').textContent=money.format(outbound/100);$('#returnCostTotal').textContent=money.format(inbound/100);$('#costTotal').textContent=money.format((outbound+inbound)/100);}
function removeExtraCost(event){const remove=event.target.closest('.remove-cost');if(remove){remove.closest('.extra-cost').remove();updateCostTotal();}}
$('#addCost').onclick=()=>addCostRow();$('#addReturnCost').onclick=()=>addCostRow({},'returnExtraCosts');$('#costFields').oninput=updateCostTotal;$('#returnCostFields').oninput=updateCostTotal;$('#extraCosts').onclick=removeExtraCost;$('#returnExtraCosts').onclick=removeExtraCost;

function timelineItems(rows){return rows.flatMap(row=>row.category==='bus'&&row.return_leg?[{...row,leg:'Ida'},{...row,...row.return_leg,id:row.id,extra_costs:row.return_leg.extra_costs||[],return_leg:null,leg:'Volta'}]:[row]);}
function syncJourney(){const form=$('#itemForm'),round=isDetailedBusForm()&&form.elements.journey_type.value==='round_trip';$('#returnFields').hidden=!round;$('#returnCostFields').hidden=!round;for(const input of $('#returnCostFields').querySelectorAll('input'))input.disabled=!round;for(const key of returnKeys){const input=form.elements['return_'+key];input.disabled=!round;input.required=round&&key!=='ticket_price';}if(round){const pairs={departure_station:'arrival_station',departure_address:'arrival_address',arrival_station:'departure_station',arrival_address:'departure_address'};for(const [target,source]of Object.entries(pairs))if(!form.elements['return_'+target].value)form.elements['return_'+target].value=form.elements[source].value;}updateCostTotal();}
function prepareReturn(values){const round=values.category==='bus'&&values.journey_type==='round_trip';values.return_leg=null;if(round){const leg=Object.fromEntries(returnKeys.map(key=>[key,values['return_'+key]||'']));for(const key of returnKeys.filter(k=>k!=='ticket_price'))if(!String(leg[key]).trim())throw new Error('Preencha os dados de saída e chegada da volta.');if(leg.arrival_date+'T'+leg.arrival_time<leg.date+'T'+leg.time)throw new Error('Na volta, a chegada não pode ser anterior à partida.');if(leg.date+'T'+leg.time<values.arrival_date+'T'+values.arrival_time)throw new Error('A volta deve começar após a chegada da ida.');leg.ticket_price=leg.ticket_price===''?null:parseMoney(leg.ticket_price);leg.extra_costs=readExtraCosts('returnExtraCosts');values.return_leg=leg;}delete values.journey_type;for(const key of returnKeys)delete values['return_'+key];}
$('#journeyField').addEventListener('change',syncJourney);$('#returnFields').oninput=updateCostTotal;

function rentalCalculation(date,time,r){const start=Date.parse(date+'T'+time+'Z'),end=Date.parse(r.dropoff_date+'T'+r.dropoff_time+'Z');const days=Number.isFinite(start)&&Number.isFinite(end)&&end>start?Math.ceil((end-start)/86400000):0;const dailyCents=Math.round(Number(r.daily_price||0)*100),protectionCents=Math.round(Number(r.protection_price||0)*100);const rentalCents=days*dailyCents,coverageCents=days*protectionCents,subtotalCents=rentalCents+coverageCents;const feeCents=Math.round(subtotalCents*Number(r.fee_percent||0)/100);return {days,rental_total:rentalCents/100,protection_total:coverageCents/100,subtotal:subtotalCents/100,fee_total:feeCents/100,total:(subtotalCents+feeCents)/100,km_total:r.mileage_mode==='limited'?days*Number(r.km_per_day||0):null};}
function rentalDraft(){const form=$('#itemForm');return Object.fromEntries(rentalKeys.map(key=>[key,form.elements['rental_'+key].value]));}
function syncRental(){const form=$('#itemForm'),rental=form.elements.category.value==='car'&&form.elements.mobility_type.value==='rental_car';$('#rentalFields').hidden=!rental;for(const input of $('#rentalFields').querySelectorAll('input,select'))input.disabled=!rental;const required=['pickup_location','dropoff_date','dropoff_time','daily_price','protection_price'];for(const key of required)form.elements['rental_'+key].required=rental;const different=form.elements.rental_location_mode.value==='different',limited=form.elements.rental_mileage_mode.value==='limited';$('#rentalDropoffField').hidden=!different;$('#dropoffAddress').hidden=!different;for(const field of $('#dropoffAddress').querySelectorAll('input,select'))field.disabled=!rental||!different;form.elements.rental_dropoff_location.disabled=!rental||!different;form.elements.rental_dropoff_location.required=rental&&different;$('#rentalKmField').hidden=!limited;form.elements.rental_km_per_day.disabled=!rental||!limited;form.elements.rental_km_per_day.required=rental&&limited;if(rental){$('#titleLabel').textContent='Locadora';form.elements.title.placeholder='Nome da locadora';$('#dateLabel').textContent='Data de retirada';$('#timeLabel').textContent='Hora de retirada';form.elements.time.required=true;$('#placeField').hidden=true;form.elements.place.disabled=true;$('#urlLabel').textContent='Link da locadora';}updateRentalBreakdown();}
function updateRentalBreakdown(){const form=$('#itemForm');if($('#rentalFields').hidden)return;const draft=rentalDraft(),cost=rentalCalculation(form.elements.date.value,form.elements.time.value,draft);$('#rentalBreakdown').innerHTML='<div><span>Quantidade de diárias</span><b>'+cost.days+'</b></div><div><span>'+cost.days+' diária(s) × '+escape(money.format(Number(draft.daily_price)||0))+'</span><b>'+escape(money.format(cost.rental_total))+'</b></div><div><span>Proteção: '+cost.days+' dia(s) × '+escape(money.format(Number(draft.protection_price)||0))+'</span><b>'+escape(money.format(cost.protection_total))+'</b></div><div><span>Franquia de quilômetros</span><b>'+escape(cost.km_total===null?'Ilimitada':draft.km_per_day+' km × '+cost.days+' = '+cost.km_total+' km')+'</b></div><div><span>Subtotal (diárias + proteção)</span><b>'+escape(money.format(cost.subtotal))+'</b></div><div><span>Taxa de aluguel ('+escape(draft.fee_percent||0)+'%)</span><b>'+escape(money.format(cost.fee_total))+'</b></div><div class="rental-final"><span>Total do aluguel</span><b>'+escape(money.format(cost.total))+'</b></div>';if(!cost.days)$('#rentalBreakdown').insertAdjacentHTML('afterbegin','<p class="hint">Preencha a retirada e a devolução para calcular as diárias.</p>');}
function prepareRental(values){values.rental=null;if(values.category==='car'&&values.mobility_type==='rental_car'){const r=Object.fromEntries(rentalKeys.map(key=>[key,values['rental_'+key]||'']));for(const key of ['pickup_location','dropoff_date','dropoff_time','daily_price','protection_price'])if(!String(r[key]).trim())throw new Error('Preencha os dados obrigatórios do aluguel.');if(!values.time)throw new Error('Informe a hora de retirada.');if(!['same','different'].includes(r.location_mode)||!['limited','unlimited'].includes(r.mileage_mode)||!['basic','complete','premium'].includes(r.protection))throw new Error('Confira as opções do aluguel.');r.dropoff_location=r.location_mode==='same'?r.pickup_location:r.dropoff_location;if(r.location_mode==='same')for(const key of ['street','number','district','city','state','landmark'])r['dropoff_'+key]=r['pickup_'+key];if(!r.dropoff_location.trim())throw new Error('Informe o local de devolução.');r.daily_price=parseMoney(r.daily_price);r.protection_price=parseMoney(r.protection_price);r.fee_percent=r.fee_percent===''?0:parseMoney(r.fee_percent);if(r.fee_percent>100)throw new Error('A taxa deve estar entre 0 e 100%.');r.km_per_day=r.mileage_mode==='limited'?Number(r.km_per_day):null;if(r.mileage_mode==='limited'&&(!Number.isInteger(r.km_per_day)||r.km_per_day<0||r.km_per_day>100000))throw new Error('Informe a franquia diária de quilômetros.');const cost=rentalCalculation(values.date,values.time,r);if(!cost.days)throw new Error('A devolução deve ser posterior à retirada.');values.rental={...r,...cost};values.place=r.pickup_location;}for(const key of rentalKeys)delete values['rental_'+key];}
$('#mobilityField').addEventListener('change',syncCategory);$('#rentalFields').oninput=updateRentalBreakdown;$('#rentalFields').onchange=syncRental;$('#itemForm').elements.date.addEventListener('input',updateRentalBreakdown);$('#itemForm').elements.time.addEventListener('input',updateRentalBreakdown);

function categoryGroup(item){return item.category==='bus'?'car':item.category;}
function isBusForm(){const form=$('#itemForm');return form.elements.category.value==='car'&&form.elements.mobility_type.value==='bus';}

function itemBudget(item){if(item.rental){const total=Number(item.rental.total);return {cents:Number.isFinite(total)?Math.round(total*100):0,complete:item.rental.total!=null&&Number.isFinite(total)};}return {cents:costCents(item.ticket_price,item.extra_costs),complete:item.ticket_price!=null};}
function renderBudget(){const rows=timelineItems(items);let total=0,pending=0;$('#summary').innerHTML=Object.entries(categories).map(([key,[label]])=>{const group=rows.filter(item=>categoryGroup(item)===key);let sum=0,missing=0;for(const item of group){const value=itemBudget(item);sum+=value.cents;if(!value.complete)missing++;}total+=sum;pending+=missing;return '<details class="budget-category"><summary><span>'+label+'</span><span class="budget-numbers"><b>'+group.length.toString().padStart(2,'0')+'</b><strong>'+escape(money.format(sum/100))+'</strong></span></summary>'+(missing?'<p class="budget-pending">'+missing+' valor(es) pendente(s) · subtotal parcial</p>':'')+'<div class="budget-items">'+(group.length?group.map(item=>{const value=itemBudget(item);return '<div><span>'+escape(item.title)+(item.leg?' · '+escape(item.leg):'')+'<small>'+escape(new Date(item.date+'T12:00:00').toLocaleDateString('pt-BR'))+'</small></span><b>'+(!value.complete&&value.cents===0?'Não informado':escape(money.format(value.cents/100))+(!value.complete?' + pendente':''))+'</b></div>';}).join(''):'<p>Nenhum item cadastrado</p>')+'</div></details>';}).join('')+'<div class="budget-grand"><span>'+(pending?'Total informado':'Total da viagem')+'</span><strong>'+escape(money.format(total/100))+'</strong></div>'+(pending?'<p class="budget-pending">'+pending+' item(ns) sem preço completo.</p>':'');}

function busDate(date,time){if(!date)return 'Data a definir';const d=new Date(date+'T12:00:00');return d.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'})+(time?' · '+time.slice(0,5):' · Horário a definir');}
function busDuration(item){const start=Date.parse(item.date+'T'+(item.time||'')+'Z'),end=Date.parse(item.arrival_date+'T'+(item.arrival_time||'')+'Z');if(!Number.isFinite(start)||!Number.isFinite(end)||end<start)return 'A definir';const minutes=Math.round((end-start)/60000),hours=Math.floor(minutes/60),rest=minutes%60;return hours+'h'+(rest?' '+rest.toString().padStart(2,'0')+'min':'');}
function renderBusCard(item){const value=itemBudget(item),price=value.complete?money.format(value.cents/100):value.cents?money.format(value.cents/100)+' + pendente':'Não informado';return '<button class="card bus-summary-card" data-id="'+escape(item.id)+'" aria-label="Editar viagem de ônibus '+escape(item.title)+'"><div class="bus-summary-left"><span class="bus-field-label">Saída</span><strong class="bus-datetime">'+escape(busDate(item.date,item.time))+'</strong><h4>'+escape(item.departure_station||item.place||'Terminal a definir')+'</h4><p>'+escape(item.departure_address||'Endereço não informado')+'</p></div><div class="bus-summary-center"><span class="tag">'+escape(busTypes[item.bus_type||'interstate']||'Ônibus')+(item.leg?' · '+escape(item.leg):'')+'</span><h3>'+escape(item.title)+'</h3><p class="bus-summary-duration">Duração: <b>'+escape(busDuration(item))+'</b></p>'+(item.reference?'<p>Reserva: '+escape(item.reference)+'</p>':'')+'</div><div class="bus-summary-right"><span class="bus-field-label">Chegada</span><strong class="bus-datetime">'+escape(busDate(item.arrival_date,item.arrival_time))+'</strong><h4>'+escape(item.arrival_station||'Terminal a definir')+'</h4><p>'+escape(item.arrival_address||'Endereço não informado')+'</p></div><div class="stay-footer"><div class="stay-final-price"><span>Preço final</span><strong>'+escape(price)+'</strong></div><div class="stay-meta"><span class="status '+(item.status==='A planejar'?'pending':'')+'">'+escape(item.status)+'</span></div></div></button>';}

function isDetailedBusItem(item){return item.category==='bus'&&['interstate','intercity'].includes(item.bus_type||'interstate');}
function isDetailedBusForm(){return isBusForm()&&['interstate','intercity'].includes($('#itemForm').elements.bus_type.value);}
function preparePointTransport(values){values.transport_details=null;const point=(values.category==='bus'&&!isDetailedBusItem(values))||values.mobility_type==='app';if(values.category==='bus'&&!busTypes[values.bus_type])throw new Error('Selecione um tipo de ônibus válido.');if(point){const origin=(values.point_origin||'').trim(),destination=(values.point_destination||'').trim();if(!origin||!destination||!values.time)throw new Error('Informe os pontos de partida e destino e o horário previsto.');const metro=values.category==='bus'&&values.bus_type==='metropolitan';if(metro&&(!values.point_origin_city?.trim()||!values.point_destination_city?.trim()))throw new Error('Informe os municípios de origem e destino.');values.departure_station=origin;values.arrival_station=destination;values.departure_address='';values.arrival_address='';values.arrival_date=null;values.arrival_time=null;values.place=origin;values.transport_details={origin_city:metro?values.point_origin_city.trim():'',destination_city:metro?values.point_destination_city.trim():''};}for(const key of ['point_origin','point_destination','point_origin_city','point_destination_city'])delete values[key];}
function renderPointCard(item){const label=item.category==='bus'?(busTypes[item.bus_type]||'Ônibus'):'Transporte por App',cost=itemBudget(item);return '<button class="card point-card" data-id="'+escape(item.id)+'" aria-label="Editar '+escape(label)+' '+escape(item.title)+'"><div class="point-card-top"><span class="point-label">'+(item.category==='bus'?'🚌':'🚘')+' '+escape(label)+'</span><span class="status '+(item.status==='A planejar'?'pending':'')+'">'+escape(item.status)+'</span></div><div class="point-card-heading"><h3>'+escape(item.title)+'</h3><strong>'+escape(busDate(item.date,item.time))+'</strong></div><div class="point-card-route"><div><span>Partida</span><h4>'+escape(item.departure_station||item.place||'A definir')+'</h4>'+(item.transport_details?.origin_city?'<p>'+escape(item.transport_details.origin_city)+'</p>':'')+'</div><span class="point-route-arrow" aria-hidden="true">→</span><div><span>Destino</span><h4>'+escape(item.arrival_station||'A definir')+'</h4>'+(item.transport_details?.destination_city?'<p>'+escape(item.transport_details.destination_city)+'</p>':'')+'</div></div><div class="point-card-foot"><span>Preço final: <b>'+escape(cost.complete?money.format(cost.cents/100):'Não informado')+'</b></span><span class="arrow" aria-hidden="true">↗</span></div></button>';}
$('#busTypeField').addEventListener('change',syncCategory);

function stayNights(entry,departure){if(!/^\d{4}-\d{2}-\d{2}$/.test(entry||'')||!/^\d{4}-\d{2}-\d{2}$/.test(departure||''))return 0;const nights=(Date.parse(departure+'T00:00:00Z')-Date.parse(entry+'T00:00:00Z'))/86400000;return Number.isInteger(nights)&&nights>0?nights:0;}
function updateStayBreakdown(){const f=$('#itemForm');if(f.elements.category.value!=='stay')return;const nights=stayNights(f.elements.date.value,f.elements.stay_departure_date.value),price=f.elements.item_price.value;f.elements.stay_departure_date.min=f.elements.date.value;$('#stayBreakdown').innerHTML=nights?'<p>Quantidade de diárias <strong>'+nights+'</strong></p><p>Valor por diária <strong>'+(price!==''?escape(money.format(Number(price)/nights)):'A informar')+'</strong></p><p>Total da hospedagem <strong>'+(price!==''?escape(money.format(Number(price))):'A informar')+'</strong></p><p class="hint">Valor médio por diária = valor total ÷ '+nights+'. As diárias seguem as datas de entrada e saída.</p>':'<p class="hint">Informe uma data de saída posterior à entrada para calcular as diárias e o valor por diária.</p>';}
function syncStay(){const f=$('#itemForm'),stay=f.elements.category.value==='stay';for(const id of ['stayTypeField','stayFields']){$('#'+id).hidden=!stay;for(const input of $('#'+id).querySelectorAll('input'))input.disabled=!stay;}f.elements.stay_departure_date.required=stay;$('#stayBreakdown').hidden=!stay;if(stay){$('#titleLabel').textContent='Nome da hospedagem';f.elements.title.placeholder='Ex.: Hotel, pousada ou imóvel reservado';$('#dateLabel').textContent='Data de entrada';$('#timeLabel').textContent='Horário aproximado de entrada';$('#urlLabel').textContent='Link da hospedagem ou reserva';}updateStayBreakdown();}
function prepareStay(values){values.lodging=null;if(values.category==='stay'){const nights=stayNights(values.date,values.stay_departure_date);if(!stayTypes[values.stay_type])throw new Error('Selecione o tipo de hospedagem.');if(!nights)throw new Error('A data de saída deve ser posterior à data de entrada.');values.lodging={type:values.stay_type,...Object.fromEntries(stayKeys.map(key=>[key,values['stay_'+key]||''])),nights,daily_price:values.ticket_price===null?null:Math.round(values.ticket_price*100/nights)/100};}delete values.stay_type;for(const key of stayKeys)delete values['stay_'+key];}
function renderStayCard(item){const l=item.lodging||{},nights=stayNights(item.date,l.departure_date),date=value=>value?new Date(value+'T12:00:00').toLocaleDateString('pt-BR'):'A definir',time=value=>value?value.slice(0,5):'A definir';return '<button class="card stay-card" data-id="'+escape(item.id)+'" aria-label="Editar hospedagem '+escape(item.title)+'"><div class="stay-entry"><span class="stay-field-label">Entrada</span><strong class="stay-date">'+escape(date(item.date))+'</strong><p>Check-in: <b>'+escape(time(l.checkin_time))+'</b></p><p>Chegada prevista: <b>'+escape(time(item.time))+'</b></p></div><div class="stay-identity"><span class="tag">'+escape(stayTypes[l.type]||'Hospedagem')+'</span><h3>'+escape(item.title)+'</h3><p class="stay-address">'+escape(item.place||'Endereço a definir')+'</p><p class="stay-daily">'+(nights?nights+' diária(s)':'Diárias a definir')+(nights&&item.ticket_price!=null?' · '+escape(money.format(item.ticket_price/nights))+' / diária':'')+'</p>'+(item.reference?'<p class="stay-reference">Reserva: '+escape(item.reference)+'</p>':'')+'</div><div class="stay-exit"><span class="stay-field-label">Saída</span><strong class="stay-date">'+escape(date(l.departure_date))+'</strong><p>Check-out: <b>'+escape(time(l.checkout_time))+'</b></p><p>Saída prevista: <b>'+escape(time(l.departure_time))+'</b></p></div><div class="stay-footer"><div class="stay-final-price"><span>Preço final</span><strong>'+(item.ticket_price!=null?escape(money.format(item.ticket_price)):'A informar')+'</strong></div><div class="stay-meta"><span class="status '+(item.status==='A planejar'?'pending':'')+'">'+escape(item.status)+'</span></div></div></button>';}
$('#stayFields').addEventListener('input',updateStayBreakdown);$('#itemForm').elements.date.addEventListener('input',updateStayBreakdown);$('#itemForm').elements.item_price.addEventListener('input',updateStayBreakdown);

let wizardIndex=0;
function wizardSteps(){const f=$('#itemForm'),category=f.elements.category.value;if(category==='car')return ['category','mobility',...(f.elements.mobility_type.value==='bus'?['bus',...(['interstate','intercity'].includes(f.elements.bus_type.value)?['journey']:[])]:[]),'details'];if(category==='stay')return ['category','stay','details'];if(category==='tour')return ['category','tour','details'];return ['category','details'];}
function wizardLabels(){return {category:'Categoria',mobility:'Tipo de mobilidade',bus:'Tipo de ônibus',journey:'Tipo de viagem',stay:'Tipo de hospedagem',tour:'Tipo de passeio',details:'Detalhes do plano'};}
function startWizard(editing){wizardIndex=editing?wizardSteps().length-1:0;renderWizard();}
function renderWizard(){if(!$('#wizardProgress'))return;const steps=wizardSteps();wizardIndex=Math.min(wizardIndex,steps.length-1);const current=steps[wizardIndex],last=wizardIndex===steps.length-1;for(const panel of $('#itemForm').querySelectorAll('.wizard-panel')){panel.hidden=panel.dataset.step!==current;panel.classList.toggle('wizard-active',!panel.hidden);}$('#wizardProgress').innerHTML='<div class="wizard-caption"><span>Etapa '+(wizardIndex+1)+' de '+steps.length+'</span><strong>'+wizardLabels()[current]+'</strong></div><div class="wizard-track" aria-hidden="true">'+steps.map((step,i)=>'<span class="'+(i===wizardIndex?'current':i<wizardIndex?'done':'')+'"></span>').join('')+'</div>';$('#wizardBack').hidden=wizardIndex===0;$('#wizardNext').hidden=last;$('#wizardSave').hidden=!last;if($('#saveAndAdd'))$('#saveAndAdd').hidden=!last;$('#remove').hidden=!last||!$('#itemForm').elements.id.value;$('#wizardBack').disabled=busy;$('#wizardNext').disabled=busy;}
function focusWizard(){const panel=$('#itemForm .wizard-active');$('#editor').scrollTop=0;const target=panel?.querySelector('input:checked:not(:disabled),input:not([type="hidden"]):not(:disabled),select:not(:disabled),textarea:not(:disabled)');if(target)target.focus({preventScroll:true});}
function moveWizard(direction){const steps=wizardSteps();wizardIndex=Math.max(0,Math.min(wizardIndex+direction,steps.length-1));renderWizard();focusWizard();}
function initWizard(){const form=$('#itemForm'),head=form.querySelector('.dialog-head'),footer=form.querySelector('.dialog-actions');form.noValidate=true;const progress=document.createElement('div');progress.id='wizardProgress';progress.setAttribute('aria-live','polite');head.after(progress);const map={categoryPicker:'category',mobilityField:'mobility',busTypeField:'bus',journeyField:'journey',stayTypeField:'stay',tourTypeField:'tour'};for(const [id,step]of Object.entries(map)){const field=$('#'+id),panel=document.createElement('section');panel.className='wizard-panel';panel.dataset.step=step;panel.setAttribute('aria-label',wizardLabels()[step]);field.before(panel);panel.append(field);}const details=document.createElement('section');details.className='wizard-panel';details.dataset.step='details';details.setAttribute('aria-label','Detalhes do plano');for(const child of [...form.children])if(child!==head&&child!==progress&&child!==footer&&!child.classList.contains('wizard-panel')&&!(child.tagName==='INPUT'&&child.type==='hidden'))details.append(child);footer.before(details);footer.classList.add('wizard-footer');const back=document.createElement('button');back.id='wizardBack';back.type='button';back.className='quiet';back.textContent='Voltar';const next=document.createElement('button');next.id='wizardNext';next.type='button';next.className='primary';next.textContent='Próximo';const save=footer.querySelector('[type="submit"]');save.id='wizardSave';footer.prepend(back);footer.append(next);back.onclick=()=>moveWizard(-1);next.onclick=()=>moveWizard(1);form.addEventListener('submit',event=>{if(wizardIndex<wizardSteps().length-1){event.preventDefault();event.stopImmediatePropagation();moveWizard(1);}else if(!form.reportValidity()){event.preventDefault();event.stopImmediatePropagation();}},true);renderWizard();}
initWizard();

let activeDraftCategory='car',draftDirty=false,draftRestoring=false;
function draftStorageKey(){return user?.id?'boraviajar:category-drafts:v1:'+user.id:null;}
function readDraftBook(){try{return JSON.parse(localStorage.getItem(draftStorageKey())||'{}');}catch{return {};}}
function writeDraftBook(book){const key=draftStorageKey();if(!key)return false;try{localStorage.setItem(key,JSON.stringify(book));return true;}catch{setDraftStatus('Não foi possível guardar o rascunho neste navegador. Salve o item antes de sair.');return false;}}
function draftCostRows(target){return [...$('#'+target).querySelectorAll('.extra-cost')].map(row=>({description:row.querySelector('.cost-description').value,amount:row.querySelector('.cost-amount').value}));}
function captureCategoryDraft(){const form=$('#itemForm'),values={};for(const name of new Set([...form.elements].map(input=>input.name).filter(Boolean)))values[name]=form.elements[name].value;values.category=activeDraftCategory;return {values,costs:draftCostRows('extraCosts'),returnCosts:draftCostRows('returnExtraCosts'),dirty:draftDirty,updatedAt:Date.now()};}
function setDraftStatus(message){if($('#draftStatus'))$('#draftStatus').textContent=message;}
function persistCategoryDraft(){if(draftRestoring||!user||!$('#editor').open)return false;const book=readDraftBook();if(draftDirty||$('#itemForm').elements.id.value){book[activeDraftCategory]=captureCategoryDraft();book.lastCategory=activeDraftCategory;return writeDraftBook(book);}return true;}
function restoreCategoryDraft(snapshot,category){const form=$('#itemForm');draftRestoring=true;try{form.reset();form.elements.id.value='';form.elements.category.value=category;form.elements.date.value=new Date().toLocaleDateString('en-CA');renderExtraCosts([]);renderExtraCosts([],'returnExtraCosts');if(snapshot){for(const [name,value]of Object.entries(snapshot.values||{}))if(form.elements[name])form.elements[name].value=value??'';renderExtraCosts(snapshot.costs||[]);renderExtraCosts(snapshot.returnCosts||[],'returnExtraCosts');}form.elements.category.value=category;activeDraftCategory=category;draftDirty=Boolean(snapshot?.dirty);syncCategory();updateCostTotal();}finally{draftRestoring=false;}}
function beginCategoryDraft(item){const form=$('#itemForm'),book=readDraftBook(),category=item?categoryGroup(item):(book.lastCategory&&categories[book.lastCategory]?book.lastCategory:'car'),snapshot=book[category];if(!item)restoreCategoryDraft(snapshot,category);else{activeDraftCategory=category;draftDirty=false;if(snapshot?.values?.id===item.id&&snapshot.dirty)restoreCategoryDraft(snapshot,category);}setDraftStatus(draftDirty?'Rascunho recuperado. Continue de onde parou.':form.elements.id.value?'Item salvo no roteiro.':'Cada categoria será salva como um item separado.');}
function clearCategoryDraft(category){const book=readDraftBook();delete book[category];if(book.lastCategory===category)delete book.lastCategory;writeDraftBook(book);}
function setDraftBusy(value){$('#itemForm').inert=value;for(const id of ['wizardSave','saveAndAdd','wizardBack','wizardNext'])if($('#'+id))$('#'+id).disabled=value;}
async function switchDraftCategory(){const form=$('#itemForm'),target=form.elements.category.value,previous=activeDraftCategory;if(target===previous)return;if(busy){form.elements.category.value=previous;return;}form.elements.category.value=previous;syncCategory();persistCategoryDraft();let notice='';if(draftDirty){if(form.checkValidity()){let values;try{values=collectItemValues();}catch{}if(values){busy=true;setDraftBusy(true);try{await saveCurrentItem(values);notice=categories[previous][0]+': item salvo no roteiro.';}catch(error){persistCategoryDraft();notice='Não foi possível salvar '+categories[previous][0]+'. O rascunho está preservado.';}finally{busy=false;setDraftBusy(false);}}}if(!notice)notice=categories[previous][0]+': rascunho preservado. Faltam dados para salvar no roteiro.';}const book=readDraftBook();restoreCategoryDraft(book[target],target);book.lastCategory=target;writeDraftBook(book);wizardIndex=0;renderWizard();focusWizard();setDraftStatus(draftDirty?'Rascunho recuperado desta categoria.':form.elements.id.value?'Item salvo no roteiro.':'Preencha este novo item. Os dados das outras categorias estão preservados.');if(notice)toast(notice);}
function trackCategoryDraft(event){if(draftRestoring||busy||event.target.name==='category'||!$('#editor').open)return;draftDirty=true;if(persistCategoryDraft())setDraftStatus('Rascunho salvo neste navegador. Ao trocar de categoria, o item completo será salvo no roteiro.');}
const draftStatus=document.createElement('p');draftStatus.id='draftStatus';draftStatus.className='hint';draftStatus.setAttribute('role','status');$('#wizardProgress').after(draftStatus);
const saveAndAdd=document.createElement('button');saveAndAdd.id='saveAndAdd';saveAndAdd.type='submit';saveAndAdd.className='quiet';saveAndAdd.dataset.addAnother='true';saveAndAdd.textContent='Salvar e adicionar outro';$('#wizardSave').before(saveAndAdd);
$('#itemForm').addEventListener('input',trackCategoryDraft);$('#itemForm').addEventListener('change',event=>{if(event.target.name!=='category')trackCategoryDraft(event);});$('#itemForm').addEventListener('click',event=>{if(event.target.closest('.remove-cost,#addCost,#addReturnCost'))trackCategoryDraft(event);});$('#editor').addEventListener('close',()=>{if(draftDirty)persistClosedDraft();});
function persistClosedDraft(){if(!user)return;const book=readDraftBook();book[activeDraftCategory]=captureCategoryDraft();book.lastCategory=activeDraftCategory;writeDraftBook(book);}
window.addEventListener('pagehide',()=>{if($('#editor').open)persistCategoryDraft();});
renderWizard();

function installmentLastDate(first,count){if(!/^\d{4}-\d{2}-\d{2}$/.test(first||'')||!Number.isInteger(count)||count<2||count>120)return '';const start=new Date(first+'T00:00:00Z');if(!Number.isFinite(start.getTime())||start.toISOString().slice(0,10)!==first)return '';const month=start.getUTCMonth()+count-1,year=start.getUTCFullYear();const end=new Date(Date.UTC(year,month,1)),day=Math.min(start.getUTCDate(),new Date(Date.UTC(year,month+1,0)).getUTCDate());end.setUTCDate(day);return end.toISOString().slice(0,10);}
function syncPayment(){const f=$('#itemForm'),installments=f.elements.payment_method.value==='credit_installments';$('#installmentFields').hidden=!installments;for(const name of ['payment_installments','payment_first_date']){f.elements[name].disabled=!installments;f.elements[name].required=installments;}const count=Number(f.elements.payment_installments.value),first=f.elements.payment_first_date.value,last=installments?installmentLastDate(first,count):'';$('#paymentLastDate').value=last;$('#paymentSchedule').textContent=last?count+' parcelas · '+new Date(first+'T12:00:00').toLocaleDateString('pt-BR')+' até '+new Date(last+'T12:00:00').toLocaleDateString('pt-BR'):installments?'Informe a quantidade e a data da primeira parcela.':'';}
function preparePayment(values){const payer=(values.payment_payer||'').trim(),method=values.payment_method||'';values.payment=null;if(method&&!paymentMethods[method])throw new Error('Selecione uma forma de pagamento válida.');if(payer||method){const payment={payer,method,installments:null,first_date:null,last_date:null};if(method==='credit_installments'){const count=Number(values.payment_installments),first=values.payment_first_date||'',last=installmentLastDate(first,count);if(!last)throw new Error('Informe de 2 a 120 parcelas e uma data válida para a primeira parcela.');Object.assign(payment,{installments:count,first_date:first,last_date:last});}values.payment=payment;}for(const key of ['payment_payer','payment_method','payment_installments','payment_first_date'])delete values[key];}
$('#paymentFields').addEventListener('input',syncPayment);$('#paymentFields').addEventListener('change',syncPayment);syncPayment();

function tourPrice(fullPrice,fullQuantity,halfPrice,halfQuantity){const f=Number(fullQuantity),h=Number(halfQuantity);if(!Number.isInteger(f)||!Number.isInteger(h)||f<0||h<0||f>10000||h>10000)return {valid:false,total:null};if(f+h===0)return {valid:true,total:0};if((f>0&&(fullPrice===''||fullPrice==null))||(h>0&&(halfPrice===''||halfPrice==null)))return {valid:true,total:null};try{const cents=(f?Math.round(parseMoney(fullPrice)*100)*f:0)+(h?Math.round(parseMoney(halfPrice)*100)*h:0);if(cents>999999999999)return {valid:false,total:null};return {valid:true,total:cents/100};}catch{return {valid:false,total:null};}}
function updateTourPrice(){const f=$('#itemForm');if(f.elements.category.value!=='tour')return;const amount=tourPrice(f.elements.tour_full_price.value,f.elements.tour_full_quantity.value,f.elements.tour_half_price.value,f.elements.tour_half_quantity.value);$('#tourPriceSummary').innerHTML='<p>Total dos ingressos <strong>'+(amount.valid?(amount.total===null?'A informar':escape(money.format(amount.total))):'Confira os valores e quantidades')+'</strong></p>';$('#tourAdvanceHint').hidden=f.elements.tour_advance_required.value!=='yes';}
function syncTour(){const f=$('#itemForm');f.elements.tour_full_price.dataset.previousPrice=f.elements.tour_full_price.value;const tour=f.elements.category.value==='tour';for(const id of ['tourTypeField','tourFields']){$('#'+id).hidden=!tour;for(const input of $('#'+id).querySelectorAll('input'))input.disabled=!tour;}$('#placeLabel').textContent=tour?'Localização':'Local / fornecedor';f.elements.place.placeholder=tour?'Nome do local e endereço do passeio':'Endereço, rodoviária ou empresa';f.elements.place.required=tour;if(tour){$('#titleLabel').textContent='Nome do passeio';f.elements.title.placeholder='Ex.: Visita ao museu, trilha ou city tour';$('#dateLabel').textContent='Dia do passeio';$('#timeLabel').textContent='Horário do passeio';f.elements.time.required=true;$('#urlLabel').textContent='Link da reserva ou ingresso';}updateTourPrice();}
function prepareTour(values){values.tour=null;if(values.category==='tour'){if(!tourTypes[values.tour_type])throw new Error('Selecione um tipo de passeio válido.');if(!values.time||!values.place?.trim())throw new Error('Informe o horário e a localização do passeio.');const hours=values.tour_duration_hours===''?0:Number(values.tour_duration_hours),minutes=values.tour_duration_minutes===''?0:Number(values.tour_duration_minutes);if(!Number.isInteger(hours)||hours<0||hours>999||!Number.isInteger(minutes)||minutes<0||minutes>59)throw new Error('Informe uma duração estimada válida.');const full=values.tour_full_price===''||values.tour_full_price==null?null:parseMoney(values.tour_full_price),half=values.tour_half_price===''||values.tour_half_price==null?null:parseMoney(values.tour_half_price),amount=tourPrice(full,values.tour_full_quantity,half,values.tour_half_quantity);if(!amount.valid)throw new Error('Confira os preços e as quantidades de ingressos.');values.ticket_price=amount.total;values.tour={type:values.tour_type,duration_minutes:hours||minutes?hours*60+minutes:null,full_price:full,half_price:half,full_quantity:Number(values.tour_full_quantity),half_quantity:Number(values.tour_half_quantity),advance_required:values.tour_advance_required==='yes',total:amount.total};}delete values.tour_type;for(const key of tourKeys)delete values['tour_'+key];}
function renderTourCard(item){const t=item.tour||{},duration=t.duration_minutes,hours=Math.floor((duration||0)/60),minutes=(duration||0)%60,label=duration?(hours?hours+'h':'')+(minutes?' '+minutes+'min':''):'A definir';return '<button class="card bus-summary-card tour-card" data-id="'+escape(item.id)+'" aria-label="Editar passeio '+escape(item.title)+'"><div class="bus-summary-left"><span class="bus-field-label">Dia e hora</span><strong class="bus-datetime">'+escape(busDate(item.date,item.time))+'</strong><p>'+escape(t.full_quantity??0)+' inteiro(s) · '+escape(t.half_quantity??0)+' meia(s)</p></div><div class="bus-summary-center"><span class="tag">'+escape(tourTypes[t.type]?.[0]||'Passeio')+'</span><h3>'+escape(item.title)+'</h3><p>'+escape(item.place||'Localização a definir')+'</p></div><div class="bus-summary-right"><span class="bus-field-label">Duração estimada</span><strong class="bus-datetime">'+escape(label.trim())+'</strong><p>Reserva / ingresso antecipado: <b>'+(t.advance_required?'Sim':'Não')+'</b></p></div><div class="stay-footer"><div class="stay-final-price"><span>Preço final</span><strong>'+(item.ticket_price!=null?escape(money.format(item.ticket_price)):'A informar')+'</strong></div><div class="stay-meta"><span class="status '+(item.status==='A planejar'?'pending':'')+'">'+escape(item.status)+'</span></div></div></button>';}
$('#tourFields').addEventListener('input',event=>{if(event.target.name==='tour_full_price'){const full=event.target,half=$('#itemForm').elements.tour_half_price,old=full.dataset.previousPrice||'',auto=old!==''?(Math.round(Number(old)*100/2)/100).toFixed(2):'';if(full.value!==''&&(half.value===''||Number(half.value)===Number(auto)&&auto!==''))half.value=(Math.round(Number(full.value)*100/2)/100).toFixed(2);full.dataset.previousPrice=full.value;}updateTourPrice();});$('#tourFields').addEventListener('change',updateTourPrice);
